swish = FunctionLayer[# LogisticSigmoid[#] &];
net = NetChain[{LinearLayer[64], swish, LinearLayer[1]}, "Input" -> 10];
l2 = FunctionLayer[Function[{a, b}, Total[(a - b)^2]]]; l2[{1, 2}, {1, 1}] (* 1. *)

gen = NetChain[{LinearLayer[128], Ramp, LinearLayer[784], LogisticSigmoid, ReshapeLayer[{1, 28, 28}]}, "Input" -> 32];
disc = NetChain[{FlattenLayer[], LinearLayer[128], Ramp, LinearLayer[1]}, "Input" -> {1, 28, 28}];
gan = NetGANOperator[{gen, disc}];
result = NetTrain[gan, <|"Sample" -> images|>, MaxTrainingRounds -> 20];
NetExtract[result, "Generator"][RandomVariate[NormalDistribution[], 32]]

base = NetModel["ResNet-50 Trained on ImageNet Competition Data"];
feat = NetDrop[base, -3]; (* remove classifier head *)
new = NetAppend[feat, {LinearLayer[5], SoftmaxLayer[]}];
new = NetReplacePart[new, "Output" -> NetDecoder[{"Class", myClasses}]];
trained = NetTrain[new, data, LearningRateMultipliers -> {-3 ;; -1 -> 1, _ -> 0}] (* train only the head *)

lm = NetModel["Wolfram English Character-Level Language Model V1"];
so = NetStateObject[lm];
generate[n_] := StringJoin[Table[so[""] // First, n]] (* stateful sampling loop *)
step = NetUnfold[GatedRecurrentLayer[8]]; NetInformation[step, "Ports"]

net = NetModel["ResNet-50 Trained on ImageNet Competition Data"];
sal = net[img, NetPortGradient["Input"]];
Image[Abs[Total[sal, {1}]]] // ImageAdjust (* saliency map *)

enc = NetEncoder[{"Image", {64, 64}, "Grayscale"}];
Dimensions[enc[img]] (* {1, 64, 64} *)
NetChain[{ConvolutionLayer[8, 3], Ramp, FlattenLayer[], LinearLayer[2], SoftmaxLayer[]}, "Input" -> enc, "Output" -> NetDecoder[{"Class", {"cat", "dog"}}]]

enc = NetEncoder[{"Tokens"}];
enc["the quick brown fox"] (* {index1, index2, ...} *)
sentiment = NetChain[{EmbeddingLayer[64], GatedRecurrentLayer[64], SequenceLastLayer[], LinearLayer[2], SoftmaxLayer[]}, "Input" -> enc, "Output" -> NetDecoder[{"Class", {"neg", "pos"}}]]

enc = NetEncoder[{"AudioMelSpectrogram", "NumberOfFilters" -> 40, "SampleRate" -> 16000}];
Dimensions[enc[Audio["sample.wav"]]] (* {frames, 40} *)
clf = NetChain[{GatedRecurrentLayer[64], SequenceLastLayer[], LinearLayer[10], SoftmaxLayer[]}, "Input" -> enc, "Output" -> NetDecoder[{"Class", Range[0, 9]}]]

autoenc = NetChain[{FlattenLayer[], LinearLayer[32], Ramp, LinearLayer[784], LogisticSigmoid, ReshapeLayer[{1, 28, 28}]}, "Input" -> NetEncoder[{"Image", 28, "Grayscale"}], "Output" -> NetDecoder["Image"]];
trained = NetTrain[autoenc, Thread[images -> images]];
trained[images[[1]]] (* an Image *)

res = NetTrain[net, train, All, ValidationSet -> Scaled[0.15], TrainingStoppingCriterion -> <|"Criterion" -> "Loss", "Patience" -> 10|>, MaxTrainingRounds -> 200];
res["ValidationLossList"]
res["TrainedNet"]

